## `workspace-projects.md` is regenerated by the verbs that change what it
## says — and its content is derived from the ACTIVE SET plus the manifests.
##
## The index is the file a workspace's `AGENTS.md` / `CLAUDE.md` `@import`s, so
## it is the first thing every arriving agent reads. It was written only by
## `workspace init`, `workspace sync` and `health --fix`, which left the
## membership verbs — the ones people actually run day to day — changing the
## workspace without the index learning about it. A workspace measured while
## writing this had two projects enabled and 125 checkouts on disk while its
## index still said "No projects have been initialized in this workspace yet".
##
## Asserted:
##   1. `enable` writes the index even on the path that checks NOTHING out
##      (`--no-sync`). That path returns before the sync, so an index written
##      only by the sync is an index this invocation never updates — which is
##      the omission under test.
##   2. The content tracks the enabled set: a project's own `.md` overview and
##      one line per resolved repo, and `disable` removes the section and the
##      repos that were unique to it while keeping the shared one.
##   3. Repos reached through `member_sets` are listed. A generator that read
##      only `member_repos` would silently omit every shared-infrastructure
##      repo, and the omission is invisible without this check because the
##      remaining list still looks plausible.
##   4. A fragment whose checkout `path` is NESTED (`vendor/…`) is printed at
##      its declared path, not flattened to its name.
##   5. A TOML comment that contains a quoted string does not donate a phantom
##      member. A quoted-string scan over the membership array block reads
##      `--path:"../elsewhere/src"` inside a comment as a declared repo; the
##      real parser must not.
##   6. A project naming a fragment that does not exist degrades to a recorded
##      diagnostic under ITS heading while every other project still renders —
##      the index never becomes a confident empty file.
##   7. A `repos/<repo>.md` longer than its nominal one line contributes its
##      LEAD PARAGRAPH, folded onto the bullet. Emitted verbatim it ends the
##      markdown list at the first newline and spills the rest of the prose
##      into the document body — the shape the metacraft workspace's own index
##      had, where 11 of 174 sidecars are multi-paragraph.
##   8. The sidecar is located beside the FRAGMENT file, not by `[repo].name`.
##      Four fragments in that manifest repo declare a name that differs from
##      their file name, and a name-keyed lookup drops their descriptions.
##
## Falsifiability:
##   * Remove the regeneration call from `enable` and assertion 1 fails
##     (`workspace-projects.md` is absent).
##   * Remove it from `disable` and assertion 2 fails (the index still names
##     the disabled project).
##   * Make membership expansion skip `member_sets` and assertion 3 fails.
##   * Make the generator scan quoted strings instead of parsing TOML and
##     assertion 5 fails.
##   * Revert the sidecar reader to `readFile(...).strip()` and assertion 7
##     fails; revert the lookup to `repos/<repo.name>.md` and assertion 8
##     fails.
##
## Hermetic: real TOML manifests on disk in a tempdir, driven through the
## engine-built `build/bin/repro`. No mocks, no network. `git` must be on PATH
## (`disable` resolves a git tool before deciding what it may remove); its
## absence is a hard failure rather than a skip, because a skip here is
## indistinguishable from a pass.

import std/[os, strutils, tempfiles, unittest]

import repro_test_support
import repro_workspace_manifests

proc repoRoot(): string =
  result = currentSourcePath().parentDir.parentDir.parentDir

proc reproBinary(): string =
  requireBinary(repoRoot() / "build" / "bin" / addFileExt("repro", ExeExt),
    "reprobuild.apps.repro")

proc writeManifest(root, relPath, body: string) =
  let abs = root / relPath
  createDir(abs.parentDir)
  writeFile(abs, body)

proc urlPrefix(root, name, url: string) =
  writeManifest(root, "url-prefixes" / (name & ".toml"),
    "schema = \"reprobuild.workspace.url-prefix.v1\"\n\n" &
    "[url-prefix]\n" &
    "name = \"" & name & "\"\n" &
    "url = \"" & url & "\"\n")

proc repoFragment(root, fragment, path, description: string;
                  declaredName = "") =
  ## `fragment` is the FILE name under `repos/`; `declaredName` is the
  ## `[repo].name` when it differs from it (the `sel4` → `seL4` shape).
  let name = if declaredName.len > 0: declaredName else: fragment
  writeManifest(root, "repos" / (fragment & ".toml"),
    "schema = \"reprobuild.workspace.repo.v1\"\n\n" &
    "[repo]\n" &
    "name = \"" & name & "\"\n" &
    "path = \"" & path & "\"\n" &
    "branch = \"dev\"\n" &
    "url_prefix = \"acme\"\n")
  if description.len > 0:
    writeManifest(root, "repos" / (fragment & ".md"), description & "\n")

proc repoSet(root, name: string; memberRepos: openArray[string]) =
  var body = "schema = \"reprobuild.workspace.repo-set.v1\"\n\n" &
    "member_repos = [\n"
  for m in memberRepos:
    body.add("  \"" & m & "\",\n")
  body.add("]\n\n[repo-set]\nname = \"" & name & "\"\n")
  writeManifest(root, "repo-sets" / (name & ".toml"), body)

proc projectManifest(root, name: string; memberSets, memberRepos: openArray[string];
                     inArrayComment = ""): string =
  ## `inArrayComment` is emitted INSIDE the `member_repos` array, which is
  ## where the real one sits (`projects/codetracer.toml` explains four of its
  ## members with a comment between two entries). Placing it above the array
  ## would make the test weaker than the case that motivates it.
  var body = "schema = \"reprobuild.workspace.project.v1\"\n\n"
  body.add("member_sets = [\n")
  for m in memberSets:
    body.add("  \"" & m & "\",\n")
  body.add("]\n\nmember_repos = [\n")
  for m in memberRepos:
    body.add("  \"" & m & "\",\n")
  if inArrayComment.len > 0:
    body.add(inArrayComment & "\n")
  body.add("]\n\n[project]\nname = \"" & name & "\"\ntrunk = \"dev\"\n")
  writeManifest(root, "projects" / (name & ".toml"), body)
  root / "projects" / (name & ".toml")

type
  Fixture = object
    scratch: string
    reproBin: string
    workspaceRoot: string

proc indexPath(fx: Fixture): string =
  fx.workspaceRoot / "workspace-projects.md"

proc readIndex(fx: Fixture): string =
  if not fileExists(fx.indexPath):
    return ""
  readFile(fx.indexPath)

proc setupFixture(slug: string): Fixture =
  result.scratch = createTempDir("repro-wsindex-" & slug & "-", "")
  result.reproBin = reproBinary()
  let ws = result.scratch / "workspace"
  createDir(ws)
  urlPrefix(ws, "acme", "https://git.example.invalid/acme")

  repoFragment(ws, "infra-a", "infra-a", "Shared infrastructure repo A.")
  repoFragment(ws, "shared", "shared", "Declared by both projects.")
  repoFragment(ws, "alpha-only", "alpha-only", "Only alpha declares this.")
  repoFragment(ws, "beta-only", "beta-only", "Only beta declares this.")
  # A fragment whose checkout path is nested under a subdirectory — the shape
  # a vendored reference tree takes (`reprobuild/references/llvm-project`).
  repoFragment(ws, "nested-tree", "vendor/nested-tree",
    "Vendored tree checked out under a subdirectory.")
  # A sidecar that outgrew its one line: a hard-wrapped lead paragraph plus a
  # second paragraph. Emitted verbatim it ends the markdown list at the first
  # newline; the lead paragraph must come out folded onto the bullet.
  repoFragment(ws, "wordy", "wordy",
    "A lead sentence that the author hard-wrapped\n" &
    "across two source lines.\n" &
    "\n" &
    "A second paragraph that belongs to the repo's own document and must\n" &
    "not be spliced into the index.")
  # `[repo].name` differs from the fragment file name, so a sidecar lookup
  # keyed on the NAME finds nothing and the description silently disappears.
  repoFragment(ws, "renamed-fragment", "renamed-tree",
    "Declared under a different name than its fragment file.",
    declaredName = "TheRealName")

  repoSet(ws, "shared-infrastructure", ["infra-a"])

  # A comment INSIDE the membership array carrying quoted strings — the exact
  # shape that made a quoted-string scan read `../elsewhere/src` as a declared
  # member.
  discard projectManifest(ws, "alpha",
    memberSets = ["shared-infrastructure"],
    memberRepos = ["shared", "alpha-only", "nested-tree", "wordy",
      "renamed-fragment"],
    inArrayComment = "  # Declared because alpha BUILDS against them: nim.cfg\n" &
      "  # carries --path:\"../elsewhere/src\", and see also \"phantom-repo\".")
  writeManifest(ws, "projects" / "alpha.md",
    "# Alpha\n\nThe alpha project overview prose.\n")

  discard projectManifest(ws, "beta",
    memberSets = [],
    memberRepos = ["shared", "beta-only"])
  writeManifest(ws, "projects" / "beta.md",
    "# Beta\n\nThe beta project overview prose.\n")

  result.workspaceRoot = ws

proc runRepro(fx: Fixture; args: openArray[string]): CmdResult =
  var argv = @[fx.reproBin]
  for a in args: argv.add(a)
  argv.add("--workspace-root=" & fx.workspaceRoot)
  runShell(shellCommand(argv))

suite "workspace-projects.md is owned and regenerated by repro":

  test "t_enable_writes_the_index_without_checking_anything_out":
    let fx = setupFixture("enable")
    defer: removeDir(fx.scratch)

    # Nothing has written it yet: the omission being fixed is precisely that
    # the membership verbs left this absent (or stale).
    check not fileExists(fx.indexPath)

    # `--no-sync` returns BEFORE the sync that used to be the only writer.
    let enabled = runRepro(fx, ["ws", "enable", "alpha", "--no-sync"])
    if enabled.code != 0:
      checkpoint("output: " & enabled.output)
    check enabled.code == 0
    check fileExists(fx.indexPath)

    let doc = readIndex(fx)
    check doc.contains("# Active Workspace Projects")
    check doc.contains("## alpha")
    # The placeholder is what a workspace with no active set gets; an enabled
    # workspace must never carry it.
    check "No projects have been initialized" notin doc
    # The project's own sidecar prose is composed in.
    check doc.contains("The alpha project overview prose.")

    # Every repo alpha declares, at its declared path, with its sidecar line.
    check doc.contains("- `shared` - Declared by both projects.")
    check doc.contains("- `alpha-only` - Only alpha declares this.")
    # (3) reached through `member_sets` → `repo-sets/shared-infrastructure`.
    check doc.contains("- `infra-a` - Shared infrastructure repo A.")
    # (4) nested checkout path, printed as declared.
    check doc.contains("- `vendor/nested-tree` -")
    # A sidecar longer than its one line is FOLDED onto the bullet, and only
    # its lead paragraph is taken. Both halves matter: the first assertion
    # fails if a hard-wrapped sentence is truncated at the newline, the second
    # if the whole file is spliced in and the list ends there.
    check doc.contains(
      "- `wordy` - A lead sentence that the author hard-wrapped " &
      "across two source lines.")
    check "belongs to the repo's own document" notin doc
    # The sidecar is found beside the FRAGMENT, not by `[repo].name`.
    check doc.contains(
      "- `renamed-tree` - Declared under a different name than its fragment file.")
    # (5) the comment donated nothing.
    check "../elsewhere/src" notin doc
    check "phantom-repo" notin doc
    # beta is DEFINED but not enabled, so it is not documented.
    check "## beta" notin doc
    check "beta-only" notin doc

  test "t_index_content_tracks_the_enabled_set_across_enable_and_disable":
    let fx = setupFixture("track")
    defer: removeDir(fx.scratch)

    check runRepro(fx, ["ws", "enable", "alpha", "--no-sync"]).code == 0
    let afterAlpha = readIndex(fx)
    check afterAlpha.contains("## alpha")
    check "## beta" notin afterAlpha

    let both = runRepro(fx, ["ws", "enable", "beta", "--no-sync"])
    if both.code != 0:
      checkpoint("output: " & both.output)
    check both.code == 0
    let afterBoth = readIndex(fx)
    check afterBoth.contains("## alpha")
    check afterBoth.contains("## beta")
    check afterBoth.contains("The beta project overview prose.")
    check afterBoth.contains("- `beta-only` - Only beta declares this.")

    # Disabling narrows it again. `--keep-checkouts` keeps this test's subject
    # to the INDEX rather than to directory removal, which
    # `t_workspace_membership_enable_disable` already covers.
    let off = runRepro(fx, ["ws", "disable", "beta", "--keep-checkouts"])
    if off.code != 0:
      checkpoint("output: " & off.output)
    check off.code == 0
    let afterDisable = readIndex(fx)
    check afterDisable.contains("## alpha")
    check "## beta" notin afterDisable
    check "beta-only" notin afterDisable
    # `shared` is declared by the still-enabled alpha, so it survives.
    check afterDisable.contains("- `shared` - Declared by both projects.")

  test "t_a_project_naming_a_missing_fragment_degrades_to_a_diagnostic":
    let fx = setupFixture("broken")
    defer: removeDir(fx.scratch)

    # `gamma` names a fragment that was never written. `enable` records the
    # membership and reports that it could not resolve the manifest; the index
    # must still render every project that DOES resolve, with the failure
    # recorded under the offending project rather than swallowed.
    discard projectManifest(fx.workspaceRoot, "gamma",
      memberSets = [], memberRepos = ["no-such-fragment"])

    check runRepro(fx, ["ws", "enable", "alpha", "--no-sync"]).code == 0
    let broken = runRepro(fx, ["ws", "enable", "gamma", "--no-sync"])
    if broken.code != 0:
      checkpoint("output: " & broken.output)
    check broken.code == 0

    let doc = readIndex(fx)
    check doc.contains("## alpha")
    check doc.contains("- `alpha-only` - Only alpha declares this.")
    check doc.contains("## gamma")
    check doc.contains("Error resolving repositories:")
    check doc.contains("no-such-fragment")

  test "t_enabling_a_repo_set_by_name_documents_its_repos":
    # An ACTIVE SET entry need not be a `projects/*.toml`: `enable` accepts any
    # name `definedProjectNames` reports, and that includes repo-sets. A
    # generator that only knew `projects/` printed "the active manifest was not
    # found on disk" for a set every other verb resolves fine.
    let fx = setupFixture("set")
    defer: removeDir(fx.scratch)

    let enabled = runRepro(fx, ["ws", "enable", "shared-infrastructure",
      "--no-sync"])
    if enabled.code != 0:
      checkpoint("output: " & enabled.output)
    check enabled.code == 0

    let doc = readIndex(fx)
    check doc.contains("## shared-infrastructure")
    check "was not found on disk" notin doc
    check doc.contains("- `infra-a` - Shared infrastructure repo A.")
